parameters.jsCode:
const inp = $input.first().json;

// Desempacar inputs (vienen de 02 Contexto + extracción de mensaje en 00)
const msgData = {
  telefono: inp.telefono,
  texto: inp.texto || '',
  nombreContacto: inp.nombreContacto || ''
};
const configData = { records: [{ fields: inp.configEmpresa || {} }] };
const waConfigData = { records: [{ fields: inp.waConfig || {} }] };
const leadData = { records: inp.leadId ? [{ id: inp.leadId, fields: inp.leadFields || {} }] : [] };
const productosData = { records: (inp.productosRaw || []) };

// Inyectar en scope como lo esperaría el código original
const _extraer = () => msgData;
const _config = () => configData;
const _waConfig = () => waConfigData;
const _lead = () => leadData;
const _productos = () => productosData;


const config = configData.records?.[0]?.fields || {};
const waConfig = waConfigData.records?.[0]?.fields || {};
const emailVendedor = config.WA_Email_Vendedor || 'risosadmi@gmail.com';
const followup24 = waConfig.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || '';

const leadExistente = leadData.records?.[0];
const leadId = leadExistente?.id || null;
const leadFields = leadExistente?.fields || {};

// ── Cargar estado desde Airtable ─────────────────────────────────────────────
let datosRecolectados = {
  producto: leadFields.Articulo || null,
  medidas: leadFields['Medidas y Peso'] || null,
  fecha: null,
  tipo_cajon: null,
  proteccion_extra: null,
  correo_contacto: null,
  nombre_cliente: leadFields.Nombre_Contacto || null,
  tipo_flujo: null  // 'cotizacion' | 'consulta' | null = sin identificar aún
};

let notasOriginal = {};
try {
  const notas = leadFields.Notas || '';
  if (notas && notas.trim().startsWith('{')) {
    const stored = JSON.parse(notas);
    notasOriginal = stored;
    if (stored.tipo_cajon)       datosRecolectados.tipo_cajon = stored.tipo_cajon;
    if (stored.correo_contacto)  datosRecolectados.correo_contacto = stored.correo_contacto;
    if (stored.nombre_cliente && !datosRecolectados.nombre_cliente) datosRecolectados.nombre_cliente = stored.nombre_cliente;
    if (stored.proteccion_extra !== null && stored.proteccion_extra !== undefined) datosRecolectados.proteccion_extra = stored.proteccion_extra;
    if (stored.fecha)            datosRecolectados.fecha = stored.fecha;
    if (stored.tipo_flujo)       datosRecolectados.tipo_flujo = stored.tipo_flujo;
  }
} catch(e) {}

const r3 = leadFields['¿Protección adicional?'] || '';
if (r3 === 'true')  datosRecolectados.proteccion_extra = true;
else if (r3 === 'false') datosRecolectados.proteccion_extra = false;

const estado = leadFields.Estado || 'Nuevo';
const cotizacionEnviada = notasOriginal.cotizacion_enviada === true || ['Vendedor notificado', 'Cotizacion_Enviada'].includes(estado);
const historialRaw = leadFields.Historial_Mensajes || '';
// Truncar historial a los últimos 10 intercambios para no exceder el contexto de Groq
const historial = historialRaw
  ? historialRaw.split('\n').slice(-20).join('\n')  // ~10 pares cliente/bot
  : '';
const esNuevo = !leadId;

// Catálogo
const catalogoProductos = (productosData.records || []).map(r => {
  const f = r.fields;
  return Object.entries(f).find(([k]) => k.includes('Nombre de Servicio'))?.[1] || '';
}).filter(l => l.length > 2).join(', ');

let catalogoFinal = catalogoProductos;

const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes' : 'buenas noches';
const saludo = saludoHora.charAt(0).toUpperCase() + saludoHora.slice(1);

const texto      = (msgData.texto || '').trim();
const textoLower = texto.toLowerCase();
const hasDigits  = /\d/.test(texto);
const isGreeting = /^(hola[sa]?\b|hi\b|buenas\b|buenos\b|hey\b|good\s|morning|afternoon|evening|hello\b)/i.test(texto);
const isServiceMention = /\b(cotiz|lavadora|refrigerador|mueble|nevera|estufa|máquina|machine|embalaje|caja|cajón|crate|pack|madera|necesito|quiero|quisiera|me gustaría|precio|medid|pulgad)\b/i.test(texto);

// ── Máquina de estado ─────────────────────────────────────────────────────────
const cleanCheck = v => {
  if (typeof v === 'boolean') return v;
  if (!v || ['desconocido','null','undefined'].includes(String(v).toLowerCase().trim())) return null;
  return v;
};

const calcProximoPaso = d => {
  if (cotizacionEnviada)          return 'POST_COTIZACION';
  if (esNuevo && !datosRecolectados.nombre_cliente) return 'PRIMER_CONTACTO';
  if (!cleanCheck(d.nombre_cliente)) return 'PEDIR_NOMBRE';
  if (!d.tipo_flujo)              return 'IDENTIFICAR_NECESIDAD';
  if (d.tipo_flujo === 'consulta') return 'FLUJO_CONSULTA';
  // cotizacion flow
  if (!cleanCheck(d.producto))    return 'PEDIR_PRODUCTO';
  if (!cleanCheck(d.medidas))     return 'PEDIR_MEDIDAS';
  if (!cleanCheck(d.tipo_cajon))  return 'PEDIR_TIPO_CAJON';
  if (d.proteccion_extra === null || d.proteccion_extra === undefined) return 'PEDIR_PROTECCION';
  if (!cleanCheck(d.fecha))       return 'PEDIR_FECHA';
  return 'LISTO_PARA_COTIZAR';
};

let proximoPaso = calcProximoPaso(datosRecolectados);
const proximoPasoInicial = proximoPaso; // paso en que estaba Alex ANTES de este mensaje
const nombreAntesMensaje = datosRecolectados.nombre_cliente;

// ── detectarIntento: detecta si un mensaje es cotización o consulta ────────────
// IDENTIFICAR NECESIDAD: cotización vs consulta (detección exhaustiva)
const detectarIntento = (txt) => {
  const n = txt.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const hd = /\d/.test(txt);
  const tienePregunta = /[?¿]/.test(txt);

  // — Señales de CONSULTA —
  const cTiempo   = /(cuanto).{0,15}(demora|tarda|tiempo|dias?|semanas?|plazo)/.test(n) || /(how (long|fast|quick|soon)|demoran?|tardan?|plazo|days? (to|for))/.test(n);
  const cCatalogo = /(que tipos?|what types?|what kind[s]?|what do you (make|offer|sell|have|do)|que (ofrecen|hacen|venden|tienen|manejan|trabajan)|tipos? de|clases? de|opciones?|disponibles?|que (fabrican|producen|construyen))/.test(n);
  const cOper     = /(horario|schedule|hours?|abiertos?|abren|cierran|open|close|located|location|address|direcc|donde estan|donde esta|where are you|work.{0,5}(weekend|saturday|sunday|sabado|domingo|fin de semana)|trabajan.{0,10}(sabado|domingo|fin de semana|weekend)|payment|pago|aceptan|acepta|cobran con|metodo|forma de pag|tarjeta|efectivo|transferencia|deposito|banco|factura|invoice|recibo|estan en|son de|llegan a|near|cerca de)/.test(n);
  const cProceso  = /(como (funciona|trabajan|hacen|es el proceso|se hace)|how (does|do) (it|you|the)|proceso|ispm|nimf|certificad|garantia|warranty|incluye|include|que incluye|included|material|madera|wood|tipo de (madera|material)|que.{0,10}(incluye|viene|trae|contiene))/.test(n);
  const cPueden   = /^(pueden|can you|do you|are you|es posible|hacen|fabrican|manejan|trabajan con|atienden|van a|vienen a|tienen servicio|ofrecen servicio|make|build|deliver|come to|work with|handle)/.test(n);
  const cPrecioG  = /(descuento|discount|precios? (en general|normal|promedio|aprox|standard|habitual)|cuanto salen en promedio|precio base|precio minimo|precio maximo|cuales? son (sus|los) precio|what are (your|the) price|how much (do you|does it) (charge|cost) (in general|usually|typically|on average|generally|normally)|rango de precio|cuanto.{0,10}(salen|valen).{0,10}(mas o menos|aprox|por lo general)|minimo de pedido|minimum order)/.test(n);
  const cInfo     = /(que ofrecen|que hacen|que servicios|what (do|does).{0,10}(offer|make|sell|do)|tell me about|explica|explain|informac|info (sobre|de|acerca)|info$|more about|servicios que|solo quier.{0,2} saber|just want to know|queria saber|quiero saber|quisiera saber|saber (sobre|acerca|de los?|de las?|que son|como son)|puede darme|podria darme|me puede dar|me podria dar|cuéntame|cuentame|hablar de|habla(me)? (de|sobre)|que (es|son) (un[ao]?s?|los?|las?)?\s*(caj|jaula|palet|cuna|plataforma|embalaje))/.test(n);

  // — Señales de COTIZACIÓN —
  const qDirecto   = /(cotiz[a-z]*|presupuest[a-z]*|quot[a-z]*|estimat[a-z]*)/.test(n);
  const qNecesidad = /(necesito|quiero|i need|i want|i.?d like|looking for).{0,25}(caj[oa]|cajones|embal|empacar?|crate|box|pack|palet|plataforma|jaula|cuna[s]?|packaging|wooden)/.test(n);
  const qAccion    = /(embalar|empacar|enviar|exportar|mandar|ship|export|pack).{0,35}(una?|mis?|my|algo|something|equipo|maquina|motor|articulo|item|product|piezas?|partes?|generator|compressor)/.test(n);
  const qTengo     = /(tengo|have|i.?ve got|got).{0,35}(que (embalar|empacar|enviar|exportar|ship|pack)|para (embal|crat|pack|ship|export)|necesita.{0,5}(ser )?embal|to (ship|export|send))/.test(n);
  const qNecEmbal  = /(necesita.{0,10}(ser )?embalad|needs? (to be )?(crat|pack|ship)|que necesita (embal|pack|crat))/.test(n);
  const qPrecEsp   = /(cuanto).{0,30}(cuesta|vale|cobran|costo).{0,40}(caj[oa]|cajones|embal|crate|box|palet|jaula|plataforma|packaging)/.test(n);
  const qMedidas   = hd && /\d+\s*(x|×|\*|por|by)\s*\d+/.test(n);
  const qSerian    = hd && /\d.{0,30}(cuanto (seria|saldria|costaria|valdria)|how much (would|will) (it|that|be))/.test(n);
  const qDame      = /(dame|give me|send me|mandame|pasame).{0,20}(precio|price|cotiz|presupuest|quote|estimad|cost)/.test(n);
  const qEN        = /(i need a (crate|wooden box|custom box|pallet|packaging)|crate (for|my|a)|custom (box|crate|packaging)|build me|make me a (crate|box|pallet)|need.{0,15}crat)/.test(n);
  const qNeedToShip = /(need to (ship|send|export|pack|move|transport)|(i (need|want|would like) to (ship|send|export|pack|move|transport))|necesito (enviar|mandar|exportar|empacar|mover|transportar)|tengo que (enviar|mandar|exportar|empacar|mover))/.test(n);
  const qPackagingFor = /(packaging for|embalaje para|embalaje de|caja[s]? (para|de madera|de)|cajon para|cajón para|cajones para|crate for|box for|for (shipping|crating|packing|moving))/.test(n);
  const qEsPara     = /\bes\s+(para|for)\s+(?:un[ao]?\s+|a\s+|an\s+)?[\wÀ-ÿ]/.test(n);
  const qEsUn      = /\bes\s+un[ao]?\s+[\wÀ-ÿ]{3,}/.test(n);
  const qItIsFor    = /\bit is for\s+/.test(n);
  const qItIsA     = /\bit is (a|an)\s+[\wÀ-ÿ]{3,}/.test(n);
  const qParaEmb    = /\bpara\s+(transportar|enviar|embalar|empacar|ship|move|send)\s+/.test(n);
  const qTengoUn   = /\b(tengo|have)\s+(una?\s+|a\s+|an\s+)[\wÀ-ÿ]{3,}/.test(n);
  const qEsProducto = /\b(?:embalar?|empacar?|enviar|ship|pack|move|transport)\s+(?:un[ao]?|mis?|my|el|la|the|a|an|los|las)?\s*[\wÀ-ÿ]{3,}/.test(n);
  const qPrecioProd = /((precio|price).{0,30}(caj[oa]|cajones|embal|crate|box|palet|plataforma|jaula|cuna[s]?|packaging)|(caj[oa]|cajones|embal|crate|box|palet|plataforma|jaula|cuna[s]?|packaging).{0,30}(precio|price|quote|cost))/.test(n);
  const qCuantoProd = /cuanto.{0,20}(un|una|el|la)?.{0,5}(caj[oa]|cajones|embal|crate|palet|plataforma|jaula|cuna[s]?)/.test(n);
  const qISPM      = /(ispm|nimf).{0,30}(crate|cajon|cajas?|necesit|need|quiero|para|exporta)/.test(n);

  const ambiguo = /^(cuanto|how much)[.!?\s]*$/.test(n.trim()) || /^(cuanto|how much)[,\s]+(cobran|cuesta|vale)[.!?]*$/.test(n.trim());

  const esConsulta   = cTiempo || cCatalogo || cOper || cProceso || cPueden || cPrecioG || cInfo;
  const esCotizacion = qDirecto || qNecesidad || qAccion || qPrecEsp || qTengo || qNecEmbal || qMedidas || qSerian || qDame || qEN || qNeedToShip || qPackagingFor || qPrecioProd || qCuantoProd || qISPM || qEsPara || qEsUn || qItIsFor || qItIsA || qParaEmb || qTengoUn || qEsProducto;

  if (ambiguo) return 'consulta';
  if (esCotizacion && esConsulta) {
    // Si pide información explícita (y no un precio específico), es consulta
    if (cInfo && !(qDirecto || qPrecEsp || qDame)) return 'consulta';
    return (qDirecto || qNecesidad || qPrecEsp || qEN || qDame || qNecEmbal || qNeedToShip || qPackagingFor || qPrecioProd || qCuantoProd || qISPM || qEsPara || qEsUn || qItIsFor || qItIsA || qParaEmb || qTengoUn || qEsProducto) ? 'cotizacion' : 'consulta';
  }
  if (esCotizacion) return 'cotizacion';
  if (esConsulta)   return 'consulta';
  if (tienePregunta) return 'consulta';
  return null;
};

// ── Extracción de datos del mensaje actual ────────────────────────────────────
let nombreRecienExtraido = false;
// Saludo en lead existente = nueva sesión → resetear intención
if (isGreeting && !esNuevo) {
  datosRecolectados.tipo_flujo = null;
}
if (texto.length > 0) {

  // NOMBRE — tres casos:
  // 1. Prefijo explícito ("Con X", "Soy X", "Me llamo X") → cualquier estado
  // 2. "Hola soy X" / "Hi I'm X" — saludo + prefijo
  // 3. Mensaje corto solo en pasos PEDIR_NOMBRE/PRIMER_CONTACTO (mín 2 chars)
  const tienePrefijoNombre = /^(con\s+|soy\s+|me\s+llamo\s+|mi\s+nombre\s+es\s+|i'?m\s+|my\s+name\s+is\s+|it'?s\s+)/i.test(texto);
  const holaConNombre = texto.match(/^(?:hola[s]?|hi|hey|buenas)[,!\s]+(?:soy|i'?m|me\s+llamo|con)\s+([\w][\w\s]{1,30})/i);
  if (tienePrefijoNombre && !isServiceMention) {
    const nombreLimpio = texto
      .replace(/^(con\s+|soy\s+|me\s+llamo\s+|mi\s+nombre\s+es\s+|i'?m\s+|my\s+name\s+is\s+|it'?s\s+)/i, '')
      .trim();
    if (nombreLimpio.split(/\s+/).length <= 3 && !hasDigits && nombreLimpio.length >= 2) {
      datosRecolectados.nombre_cliente = nombreLimpio;
    }
  } else if (holaConNombre) {
    const nombreExtraido = holaConNombre[1].trim();
    if (nombreExtraido.length >= 2 && nombreExtraido.split(/\s+/).length <= 3) {
      datosRecolectados.nombre_cliente = nombreExtraido;
    }
  } else if ((proximoPasoInicial === 'PRIMER_CONTACTO' || proximoPasoInicial === 'PEDIR_NOMBRE') && !isGreeting && !isServiceMention) {
    const palabras = texto.split(/\s+/);
    if (palabras.length <= 4 && !hasDigits && texto.trim().length >= 2) {
      datosRecolectados.nombre_cliente = texto.trim();
    }
  }


  // NOMBRE RECIÉN EXTRAÍDO: resetear tipo_flujo para siempre pasar por IDENTIFICAR_NECESIDAD
  nombreRecienExtraido = !!(datosRecolectados.nombre_cliente && !nombreAntesMensaje);
  if (nombreRecienExtraido) {
    datosRecolectados.tipo_flujo = null; // Fuerza IDENTIFICAR_NECESIDAD, ignora tipo_flujo viejo
  }

  if (proximoPasoInicial === 'IDENTIFICAR_NECESIDAD') {
    // Si el mensaje es una presentación de nombre, no clasificar como intento todavía
    const esPresentacionNombre = /^(con\s|soy\s|me\s+llamo\s|mi\s+nombre\s|i'?m\s|my\s+name\s)/i.test(texto);
    if (!esPresentacionNombre) {
      const intento = detectarIntento(texto);
      datosRecolectados.tipo_flujo = (intento === 'cotizacion') ? 'cotizacion' : 'consulta';

      // Si ya menciona el artículo en el mismo mensaje, extraerlo para no preguntar de nuevo
      if (intento === 'cotizacion') {
        const CONTAINER = /^(caj[oó]n|caja|crate|box|embalaje|packaging|palet|jaula|plataforma|cuna|contenedor)/i;
        function cleanProd(s) {
          if (!s) return null;
          let c = s.trim();
          c = c.replace(/\s+(?:que|which|that|quien)\s+.*$/i, '');
          c = c.replace(/\s+(?:and|y)\s+(?:ship|pack|crate|move|send|export|transport|necesito|need)\b.*$/i, '');
          c = c.replace(/\s+(?:from|desde|hacia|to)\s+\S+.*$/i, '');
          c = c.replace(/\s+(?:para|for)\s+(?:enviarlo|shipment|ship|send|it|ella|él)\b.*$/i, '');
          return c.trim();
        }
        const productPatterns = [
          /\b(?:tengo|have|i.?ve got)\s+(?:una?\s+|a\s+|an\s+)([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?=\s+(?:que|which|that)\s+|\s*$|[,\.;?¿])/i,
          /\b(?:embalar?|empacar?|enviar|exportar|exportando|enviando|empacando|embalando|transportar|transportando|mandar|llevar)\s+(?!(?:de|desde|a|al|hacia|para)\b)(?:(?:un[ao]?|el|la|los|las|mi|mis)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and|para)\s)/i,
          /\b(?:ship|pack|move|transport|export)\s+(?!(?:and|or)\s)(?:(?:a|an|my|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and)\s)/i,
          /(?<!a )(?<!an )\bcrate\s+(?!(?:and|or|is|was|for)\s)(?:(?:a|an|my|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|and)\s)/i,
          /para\s+(?:transportar|enviar|embalar|empacar|ship|move|send)\s+(?:(?:un[ao]?|my|mi|el|la|a)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and)\s)/i,
          /\b(?:es\s+(?:para|for)|it\s+is\s+for|is\s+it\s+for)\s+(?:(?:un[ao]?|el|la|los|las|my|mi|a|an|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and)\s)/i,
          /\b(?:caj[oó]n?|caja|crate|box)\s+(?:para|for)\s+(?:(?:un[ao]?|my|mi|el|la|a|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and)\s)/i,
          /\b(?:crate|box|cajón|caja)\b.{0,25}\bfor\s+(?:(?:a|an|the|my)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:and|que|which|that)\s)/i,
          /\b(?:packaging|embalaje|crating|packing)\s+(?:for|para)\s+(?:(?:a|an|my|the|un[ao]?|el|la)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and)\s)/i,
          /\b(?:necesita|needs?|requires?)\s+(?:(?:un[ao]?|a|an|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and)\s)/i,
          /,?\s*de\s+un[ao]?\s+([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|y|and|para)\s)/i,
          /for\s+(?:shipping|packing|crating|moving)\s+(?:(?:a|an|my|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:and|que|that)\s)/i,
          /\b(?:embalando|empacando|crating|packing)\s+(?:(?:un[ao]?|a|an|my|the)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|and)\s)/i,
          /(?:cuesta|cobran|precio|cost|charge)\s+(?:embalar?\s+|empacar?\s+|crating?\s+|packing?\s+)?(?:(?:un[ao]?|a|an|the|my)\s+)?([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|and)\s)/i,
          /\b(?:es|it\s+is)\s+(?:un[ao]?|a|an)\s+([\wÀ-ÿ][\wÀ-ÿ\s]{2,50}?)(?:\s*$|[,\.;?¿]|\s+(?:que|which|that|de|of)\s)/i,
        ];
        for (const pat of productPatterns) {
          const m = texto.match(pat);
          if (m && m[1]) {
            const c = cleanProd(m[1]);
            if (c && c.length >= 3 && c.split(/\s+/).length <= 6 && !CONTAINER.test(c)) {
              datosRecolectados.producto = c;
              break;
            }
          }
        }
        if (!datosRecolectados.producto) {
